fwd_t = 0.0
phase = 0
def control(obs):
    global fwd_t, phase
    dt = obs.get('dt', 0.1) or 0.1
    mot = obs.get('motion') or {}
    v = mot.get('v_mps', 0.0) or 0.0
    if phase == 0:
        if v > 0.1:
            fwd_t += dt
        if fwd_t < 2.5:
            return (0.0, 0.4, -23)
        phase = 1
    h = obs.get('hitch_deg', 0.0) or 0.0
    rig = obs.get('rig') or {}
    tr = rig.get('trailer_rear') or [0.0, 0.0]
    y = tr[1]
    hdes = -15.0 * (y + 0.5)
    hdes = max(-8.0, min(3.0, hdes))
    s = 3.0 * (h - hdes)
    s = max(-20.0, min(20.0, s))
    return (s, -0.25, -23)

