FW = False
MOVED = 0.0
def control(obs):
    global FW, MOVED
    st = obs['status']
    dt = obs['dt']
    v = obs['motion']['v_mps']
    h = obs['hitch_deg']
    y = obs['rig']['trailer_rear'][1]
    if (not FW) and st == 'PINNED':
        FW = True
        MOVED = 0.0
    if FW:
        if v > 0.2:
            MOVED += dt
        if MOVED < 3.0:
            return (0.0, 0.8, 180)
        FW = False
    steer = 2.5 * h + 8.0 * y
    steer = max(-30.0, min(30.0, steer))
    return (steer, -0.6, 180)

