S = {'mode': 'rev', 'acc': 0.0, 'stuck': 0.0}
def control(obs):
    m = obs.get('motion', {}) or {}
    v = m.get('v_mps', 0.0) or 0.0
    hold = m.get('hold_s', 0.0) or 0.0
    h = obs.get('hitch_deg', 0.0) or 0.0
    dt = obs.get('dt', 0.1) or 0.1
    if S['mode'] == 'rev':
        if hold <= 0 and abs(v) < 0.05:
            S['stuck'] += dt
        else:
            S['stuck'] = 0.0
