    hold = m.get('hold_s', 0.0) or 0.0
    h = obs.get('hitch_deg', 0.0) or 0.0
    dt = obs.get('dt', 0.1) or 0.1
    if S['mode'] == 'fwd':
        if hold <= 0 and v > 0.05:
            S['d'] += v * dt
        if S['d'] >= 3.0:
            S['mode'] = 'rev'
            S['stuck'] = 0.0
        else:
            return (0.0, 0.6, -41.0)
    if hold <= 0 and abs(v) < 0.05:
        S['stuck'] += dt
    else:
        S['stuck'] = 0.0
    if S['stuck'] >= 1.5:
        S['mode'] = 'fwd'
        S['d'] = 0.0
        S['stuck'] = 0.0
        return (0.0, 0.6, -41.0)
    steer = max(-42.0, min(42.0, 2.0 * (h - 2.0)))
    return (steer, -0.4, -41.0)

